(() => {
  const APPEAL_WINDOW_DAYS = 120;
  const MS_PER_DAY = 864e5;
  const ALLOWED_FIELDS = ["denialDate", "checkDate"];
  const DATE_RE = /^(\d{4})-(\d{2})-(\d{2})$/;
  function toDayNumber(value, name) {
    if (typeof value !== "string") throw new Error("invalid date: " + name);
    const m = DATE_RE.exec(value);
    if (!m) throw new Error("invalid date: " + name);
    const y = Number(m[1]);
    const mo = Number(m[2]);
    const d = Number(m[3]);
    if (mo < 1 || mo > 12 || d < 1 || d > 31) throw new Error("invalid date: " + name);
    const dt = new Date(0);
    dt.setUTCFullYear(y, mo - 1, d);
    dt.setUTCHours(0, 0, 0, 0);
    if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== mo - 1 || dt.getUTCDate() !== d) throw new Error("invalid date: " + name);
    return Math.round(dt.getTime() / MS_PER_DAY);
  }
  function checkAppealWindow(input) {
    const obj = input !== null && typeof input === "object" ? input : {};
    for (const key of Object.keys(obj)) {
      if (!ALLOWED_FIELDS.includes(key)) throw new Error("unknown field: " + key);
    }
    for (const name of ALLOWED_FIELDS) {
      if (!Object.prototype.hasOwnProperty.call(obj, name) || obj[name] === void 0) throw new Error("missing field: " + name);
    }
    const denial = toDayNumber(obj.denialDate, "denialDate");
    const check = toDayNumber(obj.checkDate, "checkDate");
    const elapsedDays = check - denial;
    if (elapsedDays < 0) throw new Error("checkDate is before denialDate");
    const allowed = elapsedDays <= APPEAL_WINDOW_DAYS;
    const daysLeft = allowed ? APPEAL_WINDOW_DAYS - elapsedDays : 0;
    return { allowed, daysLeft, elapsedDays };
  }
  return { checkAppealWindow };
})()

