build.unitScript:
test("denial date itself is day 0: allowed with 120 days left", () => {
  assert.deepEqual(code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-01-10" }), { allowed: true, daysLeft: 120, elapsedDays: 0 });
});
test("checked 59 days after denial: allowed with 61 days left", () => {
  assert.deepEqual(code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-03-10" }), { allowed: true, daysLeft: 61, elapsedDays: 59 });
});
test("checked on day 120: still allowed with 0 days left", () => {
  assert.deepEqual(code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-05-10" }), { allowed: true, daysLeft: 0, elapsedDays: 120 });
});
test("checked on day 121: window closed with 0 days left", () => {
  assert.deepEqual(code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-05-11" }), { allowed: false, daysLeft: 0, elapsedDays: 121 });
});
test("rejects unknown field, missing field and impossible calendar date", () => {
  assert.throws(() => code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-03-10", extra: 1 }), /^Error: unknown field: extra$/);
  assert.throws(() => code.checkAppealWindow({ denialDate: "2026-01-10" }), /^Error: missing field: checkDate$/);
  assert.throws(() => code.checkAppealWindow({ denialDate: "2026-02-30", checkDate: "2026-03-10" }), /^Error: invalid date: denialDate$/);
  assert.throws(() => code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026/03/10" }), /^Error: invalid date: checkDate$/);
});
test("rejects a check date earlier than the denial date", () => {
  assert.throws(() => code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-01-09" }), /^Error: checkDate is before denialDate$/);
});

build.testScript:
test("Denial date is day 0 and the appeal is allowed with days left equal to 120", function() {
  var actual = code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-01-10" });
  assert.deepEqual(actual, { allowed: true, daysLeft: 120, elapsedDays: 0 });
});
test("Elapsed days are calendar days after the denial date, which counts as day 0", function() {
  var actual = code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-01-11" });
  assert.deepEqual(actual, { allowed: true, daysLeft: 119, elapsedDays: 1 });
});
test("Inside the window, days left equal 120 minus elapsed days", function() {
  var actual = code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-03-10" });
  assert.deepEqual(actual, { allowed: true, daysLeft: 61, elapsedDays: 59 });
});
test("Day 119 is still allowed with 1 day left", function() {
  var actual = code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-05-09" });
  assert.deepEqual(actual, { allowed: true, daysLeft: 1, elapsedDays: 119 });
});
test("Day 120 is still allowed and days left are 0", function() {
  var actual = code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-05-10" });
  assert.deepEqual(actual, { allowed: true, daysLeft: 0, elapsedDays: 120 });
});
test("After day 120 the window is closed and days left are 0", function() {
  var actual = code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-05-11" });
  assert.deepEqual(actual, { allowed: false, daysLeft: 0, elapsedDays: 121 });
});
test("Once closed, days left stay 0 and are not negative", function() {
  var actual = code.checkAppealWindow({ denialDate: "2026-01-10", checkDate: "2026-06-10" });
  assert.deepEqual(actual, { allowed: false, daysLeft: 0, elapsedDays: 151 });
});

